package com.example.rutaculturalar;

import android.content.Intent;
import android.os.Bundle;
import android.widget.Button;
import androidx.appcompat.app.AppCompatActivity;

public class MainActivity extends AppCompatActivity {

    Button buttonStartAR;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        buttonStartAR = findViewById(R.id.buttonStartAR);

        buttonStartAR.setOnClickListener(view -> {
            Intent intent = new Intent(MainActivity.this, ARViewActivity.class);
            startActivity(intent);
        });
    }
}

package com.example.rutaculturalar;

import android.content.Intent;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.drawable.BitmapDrawable;
import android.os.Bundle;
import android.widget.Button;
import android.widget.LinearLayout;
import androidx.appcompat.app.AppCompatActivity;
import java.io.IOException;
import java.io.InputStream;

public class MainActivity extends AppCompatActivity {

    Button buttonStartAR;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        // Establecer fondo desde assets
        LinearLayout layout = findViewById(R.id.mainLayout); // Asegúrate que el LinearLayout tenga este id
        try {
            InputStream is = getAssets().open("fondo.jpg");
            Bitmap bitmap = BitmapFactory.decodeStream(is);
            layout.setBackground(new BitmapDrawable(getResources(), bitmap));
            is.close();
        } catch (IOException e) {
            e.printStackTrace();
        }

        buttonStartAR = findViewById(R.id.buttonStartAR);

        buttonStartAR.setOnClickListener(view -> {
            Intent intent = new Intent(MainActivity.this, ARViewActivity.class);
            startActivity(intent);
        });
    }
}

package com.example.rutaculturalar.ar.interfaces;

import com.google.ar.sceneform.Node;
import com.google.ar.sceneform.math.Vector3;

public interface IAR3DInfoProvider {
    void show3DInfo(String title, String description, Node parentNode, Vector3 offset);
    void hide3DInfo();
    void update3DInfoPosition(Vector3 newPosition);
    boolean isInfoVisible();
}

package com.example.rutaculturalar.ar.interfaces;

import com.google.ar.sceneform.rendering.ModelRenderable;

public interface IARModelManager {
    void loadModel(String modelPath, ModelLoadCallback callback);

    interface ModelLoadCallback {
        void onModelLoaded(ModelRenderable model);
        void onModelLoadError(String error);
    }
}

package com.example.rutaculturalar.ar.interfaces;

public interface IContextualInfoProvider {
    void showCulturalInfo(String title, String description);
    void hideCulturalInfo();
    void showTooltip(String message, float x, float y);
    void hideTooltip();
}

package com.example.rutaculturalar.ar.interfaces;

import com.google.ar.core.Plane;

public interface ISurfaceDetector {
    void enableVerticalPlaneDetection(boolean enable);
    void enableHorizontalPlaneDetection(boolean enable);
    boolean isVerticalPlane(Plane plane);
    boolean isHorizontalPlane(Plane plane);
}

package com.example.rutaculturalar.ar.managers;

import android.content.Context;
import android.graphics.Color;
import android.graphics.Typeface;
import android.view.Gravity;
import android.widget.LinearLayout;
import android.widget.TextView;
import com.example.rutaculturalar.ar.interfaces.IAR3DInfoProvider;
import com.google.ar.sceneform.Node;
import com.google.ar.sceneform.math.Vector3;
import com.google.ar.sceneform.rendering.ViewRenderable;

public class AR3DInfoProvider implements IAR3DInfoProvider {
    private Context context;
    private Node infoNode;
    private ViewRenderable infoRenderable;
    private boolean isVisible = false;

    public AR3DInfoProvider(Context context) {
        this.context = context;
    }

    @Override
    public void show3DInfo(String title, String description, Node parentNode, Vector3 offset) {
        hide3DInfo(); // Ocultar info anterior si existe

        // Crear layout para la información 3D
        LinearLayout infoLayout = createInfoLayout(title, description);

        // Crear ViewRenderable para mostrar en AR
        ViewRenderable.builder()
                .setView(context, infoLayout)
                .build()
                .thenAccept(renderable -> {
                    infoRenderable = renderable;

                    // Crear nodo para la información
                    infoNode = new Node();
                    infoNode.setParent(parentNode);
                    infoNode.setRenderable(renderable);

                    // Posicionar la información flotante
                    infoNode.setLocalPosition(offset);

                    // Escalar el nodo del popup para hacerlo más pequeño
                    infoNode.setLocalScale(new Vector3(0.6f, 0.6f, 0.6f));

                    // Hacer que siempre mire hacia la cámara
                    infoNode.setLookDirection(Vector3.forward());

                    isVisible = true;
                })
                .exceptionally(error -> {
                    error.printStackTrace();
                    return null;
                });
    }

    private LinearLayout createInfoLayout(String title, String description) {
        LinearLayout layout = new LinearLayout(context);
        layout.setOrientation(LinearLayout.VERTICAL);
        layout.setBackgroundColor(Color.argb(220, 255, 255, 255)); // Más opaco para mejor legibilidad
        layout.setPadding(20, 16, 20, 16); // Padding reducido
        layout.setGravity(Gravity.CENTER);

        // Título
        TextView titleView = new TextView(context);
        titleView.setText(title);
        titleView.setTextSize(12); // Reducido de 16 a 12
        titleView.setTypeface(null, Typeface.BOLD);
        titleView.setTextColor(Color.parseColor("#1E88E5"));
        titleView.setGravity(Gravity.CENTER);
        titleView.setMaxLines(2);

        // Descripción
        TextView descView = new TextView(context);
        descView.setText(description);
        descView.setTextSize(9);
        descView.setTextColor(Color.parseColor("#333333"));
        descView.setGravity(Gravity.CENTER);
        descView.setMaxLines(10); // Aumentado de 8 a 10 líneas
        descView.setLineSpacing(2, 1.0f);
        descView.setPadding(6, 6, 6, 0);

        layout.addView(titleView);
        layout.addView(descView);

        // Tamaño ajustado
        layout.setLayoutParams(new LinearLayout.LayoutParams(
            (int)(context.getResources().getDisplayMetrics().density * 168),
            (int)(context.getResources().getDisplayMetrics().density * 120)
        ));

        return layout;
    }

    @Override
    public void hide3DInfo() {
        if (infoNode != null) {
            infoNode.setParent(null);
            infoNode = null;
        }
        if (infoRenderable != null) {
            infoRenderable = null;
        }
        isVisible = false;
    }

    @Override
    public void update3DInfoPosition(Vector3 newPosition) {
        if (infoNode != null) {
            infoNode.setLocalPosition(newPosition);
        }
    }

    @Override
    public boolean isInfoVisible() {
        return isVisible;
    }
}

package com.example.rutaculturalar.ar.managers;

import android.content.Context;
import android.graphics.Color;
import android.graphics.Typeface;
import android.view.Gravity;
import android.widget.LinearLayout;
import android.widget.TextView;
import com.example.rutaculturalar.ar.interfaces.IAR3DInfoProvider;
import com.google.ar.sceneform.Node;
import com.google.ar.sceneform.math.Vector3;
import com.google.ar.sceneform.rendering.ViewRenderable;

public class AR3DInfoProvider implements IAR3DInfoProvider {
    private Context context;
    private Node infoNode;
    private ViewRenderable infoRenderable;
    private boolean isVisible = false;

    public AR3DInfoProvider(Context context) {
        this.context = context;
    }

    @Override
    public void show3DInfo(String title, String description, Node parentNode, Vector3 offset) {
        hide3DInfo(); // Ocultar info anterior si existe

        // Crear layout para la información 3D
        LinearLayout infoLayout = createInfoLayout(title, description);

        // Crear ViewRenderable para mostrar en AR
        ViewRenderable.builder()
                .setView(context, infoLayout)
                .build()
                .thenAccept(renderable -> {
                    infoRenderable = renderable;

                    // Crear nodo para la información
                    infoNode = new Node();
                    infoNode.setParent(parentNode);
                    infoNode.setRenderable(renderable);

                    // Posicionar la información flotante
                    infoNode.setLocalPosition(offset);

                    // Escalar el nodo del popup para hacerlo más pequeño
                    infoNode.setLocalScale(new Vector3(0.6f, 0.6f, 0.6f));

                    // IMPORTANTE: Hacer que siempre mire hacia la cámara correctamente
                    infoNode.setLookDirection(Vector3.back()); // Cambiar de forward() a back()

                    // Configurar para que siempre se oriente hacia la cámara automáticamente
                    infoNode.setOnUpdateListener(frameTime -> {
                        // Obtener la posición de la cámara
                        com.google.ar.sceneform.Camera camera = infoNode.getScene().getCamera();
                        if (camera != null) {
                            Vector3 cameraPosition = camera.getWorldPosition();
                            Vector3 nodePosition = infoNode.getWorldPosition();
                            Vector3 direction = Vector3.subtract(cameraPosition, nodePosition);
                            infoNode.setLookDirection(direction);
                        }
                    });

                    isVisible = true;
                })
                .exceptionally(error -> {
                    error.printStackTrace();
                    return null;
                });
    }

    private LinearLayout createInfoLayout(String title, String description) {
        LinearLayout layout = new LinearLayout(context);
        layout.setOrientation(LinearLayout.VERTICAL);
        layout.setBackgroundColor(Color.argb(220, 255, 255, 255)); // Más opaco para mejor legibilidad
        layout.setPadding(20, 16, 20, 16); // Padding reducido
        layout.setGravity(Gravity.CENTER);

        // Título
        TextView titleView = new TextView(context);
        titleView.setText(title);
        titleView.setTextSize(12); // Reducido de 16 a 12
        titleView.setTypeface(null, Typeface.BOLD);
        titleView.setTextColor(Color.parseColor("#1E88E5"));
        titleView.setGravity(Gravity.CENTER);
        titleView.setMaxLines(2);

        // Descripción
        TextView descView = new TextView(context);
        descView.setText(description);
        descView.setTextSize(9);
        descView.setTextColor(Color.parseColor("#333333"));
        descView.setGravity(Gravity.CENTER);
        descView.setMaxLines(10); // Aumentado de 8 a 10 líneas
        descView.setLineSpacing(2, 1.0f);
        descView.setPadding(6, 6, 6, 0);

        layout.addView(titleView);
        layout.addView(descView);

        // Tamaño ajustado
        layout.setLayoutParams(new LinearLayout.LayoutParams(
            (int)(context.getResources().getDisplayMetrics().density * 168),
            (int)(context.getResources().getDisplayMetrics().density * 120)
        ));

        return layout;
    }

    @Override
    public void hide3DInfo() {
        if (infoNode != null) {
            infoNode.setParent(null);
            infoNode = null;
        }
        if (infoRenderable != null) {
            infoRenderable = null;
        }
        isVisible = false;
    }

    @Override
    public void update3DInfoPosition(Vector3 newPosition) {
        if (infoNode != null) {
            infoNode.setLocalPosition(newPosition);
        }
    }

    @Override
    public boolean isInfoVisible() {
        return isVisible;
    }
}

package com.example.rutaculturalar.ar.managers;

import android.content.Context;
import android.net.Uri;
import android.widget.Toast;
import com.example.rutaculturalar.ar.interfaces.IARModelManager;
import com.google.ar.sceneform.rendering.ModelRenderable;

public class ARModelManager implements IARModelManager {
    private Context context;

    public ARModelManager(Context context) {
        this.context = context;
    }

    @Override
    public void loadModel(String modelPath, ModelLoadCallback callback) {
        ModelRenderable.builder()
                .setSource(context, Uri.parse(modelPath))
                .setIsFilamentGltf(true)
                .build()
                .thenAccept(callback::onModelLoaded)
                .exceptionally(error -> {
                    callback.onModelLoadError("Error cargando modelo: " + error.getMessage());
                    return null;
                });
    }
}

package com.example.rutaculturalar.ar.managers;

import android.app.Activity;
import android.view.LayoutInflater;
import android.view.View;
import android.widget.TextView;
import android.widget.PopupWindow;
import com.example.rutaculturalar.R;
import com.example.rutaculturalar.ar.interfaces.IContextualInfoProvider;

public class ContextualInfoProvider implements IContextualInfoProvider {
    private Activity activity;
    private PopupWindow infoPopup;
    private PopupWindow tooltipPopup;

    public ContextualInfoProvider(Activity activity) {
        this.activity = activity;
    }

    @Override
    public void showCulturalInfo(String title, String description) {
        if (infoPopup != null && infoPopup.isShowing()) {
            infoPopup.dismiss();
        }

        View popupView = LayoutInflater.from(activity).inflate(R.layout.cultural_info_popup, null);
        TextView titleView = popupView.findViewById(R.id.cultural_title);
        TextView descriptionView = popupView.findViewById(R.id.cultural_description);

        titleView.setText(title);
        descriptionView.setText(description);

        infoPopup = new PopupWindow(popupView,
            (int)(activity.getResources().getDisplayMetrics().density * 300),
            (int)(activity.getResources().getDisplayMetrics().density * 200),
            true);

        infoPopup.showAtLocation(activity.findViewById(android.R.id.content),
            android.view.Gravity.CENTER, 0, 0);
    }

    @Override
    public void hideCulturalInfo() {
        if (infoPopup != null && infoPopup.isShowing()) {
            infoPopup.dismiss();
        }
    }

    @Override
    public void showTooltip(String message, float x, float y) {
        if (tooltipPopup != null && tooltipPopup.isShowing()) {
            tooltipPopup.dismiss();
        }

        View tooltipView = LayoutInflater.from(activity).inflate(R.layout.tooltip_popup, null);
        TextView messageView = tooltipView.findViewById(R.id.tooltip_message);
        messageView.setText(message);

        tooltipPopup = new PopupWindow(tooltipView,
            (int)(activity.getResources().getDisplayMetrics().density * 200),
            (int)(activity.getResources().getDisplayMetrics().density * 50),
            false);

        tooltipPopup.showAtLocation(activity.findViewById(android.R.id.content),
            android.view.Gravity.NO_GRAVITY, (int)x, (int)y);
    }

    @Override
    public void hideTooltip() {
        if (tooltipPopup != null && tooltipPopup.isShowing()) {
            tooltipPopup.dismiss();
        }
    }
}

package com.example.rutaculturalar.ar.managers;

import android.app.Activity;
import android.view.LayoutInflater;
import android.view.View;
import android.widget.TextView;
import android.widget.PopupWindow;
import com.example.rutaculturalar.R;
import com.example.rutaculturalar.ar.interfaces.IContextualInfoProvider;

public class ContextualInfoProvider implements IContextualInfoProvider {
    private Activity activity;
    private PopupWindow infoPopup;
    private PopupWindow tooltipPopup;

    public ContextualInfoProvider(Activity activity) {
        this.activity = activity;
    }

    @Override
    public void showCulturalInfo(String title, String description) {
        if (infoPopup != null && infoPopup.isShowing()) {
            infoPopup.dismiss();
        }

        View popupView = LayoutInflater.from(activity).inflate(R.layout.cultural_info_popup, null);
        TextView titleView = popupView.findViewById(R.id.cultural_title);
        TextView descriptionView = popupView.findViewById(R.id.cultural_description);
        android.widget.Button closeButton = popupView.findViewById(R.id.close_button);

        titleView.setText(title);
        descriptionView.setText(description);

        // Configurar el botón de cerrar
        closeButton.setOnClickListener(v -> {
            if (infoPopup != null && infoPopup.isShowing()) {
                infoPopup.dismiss();
            }
        });

        infoPopup = new PopupWindow(popupView, 
            (int)(activity.getResources().getDisplayMetrics().density * 320),
            (int)(activity.getResources().getDisplayMetrics().density * 400),
            true);

        // Configurar el popup para que se pueda cerrar tocando fuera
        infoPopup.setOutsideTouchable(true);
        infoPopup.setFocusable(true);

        infoPopup.showAtLocation(activity.findViewById(android.R.id.content), 
            android.view.Gravity.CENTER, 0, 0);
    }

    @Override
    public void hideCulturalInfo() {
        if (infoPopup != null && infoPopup.isShowing()) {
            infoPopup.dismiss();
        }
    }

    @Override
    public void showTooltip(String message, float x, float y) {
        if (tooltipPopup != null && tooltipPopup.isShowing()) {
            tooltipPopup.dismiss();
        }

        View tooltipView = LayoutInflater.from(activity).inflate(R.layout.tooltip_popup, null);
        TextView messageView = tooltipView.findViewById(R.id.tooltip_message);
        messageView.setText(message);

        tooltipPopup = new PopupWindow(tooltipView,
            (int)(activity.getResources().getDisplayMetrics().density * 200),
            (int)(activity.getResources().getDisplayMetrics().density * 50),
            false);

        tooltipPopup.showAtLocation(activity.findViewById(android.R.id.content),
            android.view.Gravity.NO_GRAVITY, (int)x, (int)y);
    }

    @Override
    public void hideTooltip() {
        if (tooltipPopup != null && tooltipPopup.isShowing()) {
            tooltipPopup.dismiss();
        }
    }
}

package com.example.rutaculturalar.ar.managers;

import com.google.ar.core.Frame;
import com.google.ar.core.LightEstimate;
import com.google.ar.sceneform.ArSceneView;
import com.google.ar.sceneform.Scene;

public class LightEstimationManager {
    private ArSceneView arSceneView;
    private Scene scene;

    public LightEstimationManager(ArSceneView arSceneView) {
        this.arSceneView = arSceneView;
        this.scene = arSceneView.getScene();
    }

    public void updateLighting(Frame frame) {
        if (frame == null) return;

        LightEstimate lightEstimate = frame.getLightEstimate();
        if (lightEstimate.getState() == LightEstimate.State.VALID) {
            // Obtener intensidad del entorno
            float pixelIntensity = lightEstimate.getPixelIntensity();

            // Obtener corrección de color (requiere array y offset)
            float[] colorCorrection = new float[4];
            lightEstimate.getColorCorrection(colorCorrection, 0);

            // Aplicar estimación de luz a la escena
            updateSceneLighting(pixelIntensity, colorCorrection);
        }
    }

    private void updateSceneLighting(float intensity, float[] colorCorrection) {
        if (scene != null && arSceneView != null) {
            // Obtener el renderer de Sceneform para ajustar la iluminación
            com.google.ar.sceneform.rendering.Renderer renderer = arSceneView.getRenderer();

            if (renderer != null) {
                // Ajustar intensidad (normalizar entre 0.3 y 1.5 para mejor visibilidad)
                float normalizedIntensity = Math.max(0.3f, Math.min(1.5f, intensity));

                // Aplicar corrección de color si está disponible
                if (colorCorrection.length >= 3) {
                    // Crear color con corrección basada en la estimación del entorno
                    com.google.ar.sceneform.rendering.Color ambientColor = 
                        new com.google.ar.sceneform.rendering.Color(
                            colorCorrection[0] * normalizedIntensity,
                            colorCorrection[1] * normalizedIntensity,
                            colorCorrection[2] * normalizedIntensity
                        );

                    // Actualizar la iluminación ambiental de la escena
                    renderer.setEnvironmentalHdrIntensity(normalizedIntensity);
                } else {
                    // Si no hay corrección de color disponible, solo ajustar intensidad
                    renderer.setEnvironmentalHdrIntensity(normalizedIntensity);
                }
            }
        }
    }
}

