        if (lightEstimate.getState() == LightEstimate.State.VALID) {
            // Obtener intensidad del entorno
            float pixelIntensity = lightEstimate.getPixelIntensity();

            // Obtener corrección de color (requiere array y offset)
            float[] colorCorrection = new float[4];
            lightEstimate.getColorCorrection(colorCorrection, 0);

            // Aplicar estimación de luz a la escena
            updateSceneLighting(pixelIntensity, colorCorrection);
        }
    }

    private void updateSceneLighting(float intensity, float[] colorCorrection) {
        if (scene != null && arSceneView != null) {
            // Ajustar intensidad (normalizar entre 0.3 y 1.5 para mejor visibilidad)
            float normalizedIntensity = Math.max(0.3f, Math.min(1.5f, intensity));

            // En Sceneform, la iluminación se maneja principalmente a través de los materiales
            // y la iluminación ambiental del entorno. Como no tenemos acceso directo a 
            // setEnvironmentalHdrIntensity, aplicamos los valores de manera más simple

            // Simplemente almacenar los valores para uso futuro si es necesario
            // o aplicar efectos visuales alternativos

            // Por ahora, mantenemos una implementación básica que no cause errores
            // La iluminación se manejará principalmente por ARCore y Sceneform automáticamente
        }
    }
}

package com.example.rutaculturalar.ar.managers;

import com.example.rutaculturalar.ar.interfaces.ISurfaceDetector;
import com.google.ar.core.Plane;
import com.google.ar.core.Config;
import com.google.ar.core.Session;

public class SurfaceDetector implements ISurfaceDetector {
    private Session arSession;
    private boolean verticalPlanesEnabled = true;
    private boolean horizontalPlanesEnabled = true;

    public SurfaceDetector(Session arSession) {
        this.arSession = arSession;
        configureSession();
    }

    private void configureSession() {
        if (arSession != null) {
            Config config = arSession.getConfig();
            config.setPlaneFindingMode(Config.PlaneFindingMode.HORIZONTAL_AND_VERTICAL);
            arSession.configure(config);
        }
    }

    @Override
    public void enableVerticalPlaneDetection(boolean enable) {
        this.verticalPlanesEnabled = enable;
        updatePlaneFindingMode();
    }

    @Override
    public void enableHorizontalPlaneDetection(boolean enable) {
        this.horizontalPlanesEnabled = enable;
        updatePlaneFindingMode();
    }

    private void updatePlaneFindingMode() {
        if (arSession != null) {
            Config config = arSession.getConfig();
            if (verticalPlanesEnabled && horizontalPlanesEnabled) {
                config.setPlaneFindingMode(Config.PlaneFindingMode.HORIZONTAL_AND_VERTICAL);
            } else if (horizontalPlanesEnabled) {
                config.setPlaneFindingMode(Config.PlaneFindingMode.HORIZONTAL);
            } else if (verticalPlanesEnabled) {
                config.setPlaneFindingMode(Config.PlaneFindingMode.VERTICAL);
            } else {
                config.setPlaneFindingMode(Config.PlaneFindingMode.DISABLED);
            }
            arSession.configure(config);
        }
    }

    @Override
    public boolean isVerticalPlane(Plane plane) {
        return plane.getType() == Plane.Type.VERTICAL;
    }

    @Override
    public boolean isHorizontalPlane(Plane plane) {
        return plane.getType() == Plane.Type.HORIZONTAL_UPWARD_FACING || 
               plane.getType() == Plane.Type.HORIZONTAL_DOWNWARD_FACING;
    }
}

package com.example.rutaculturalar.data;

public class MayanBallCourtInfo {

    public static class CulturalData {
        public final String title;
        public final String description;

        public CulturalData(String title, String description) {
            this.title = title;
            this.description = description;
        }
    }

    public static CulturalData getMainCourtInfo() {
        return new CulturalData(
            "Campo de Pelota Maya - Copán",
            "Este es uno de los campos de pelota más importantes de la civilización maya. " +
            "Construido entre 738-750 d.C., era el centro de rituales sagrados donde se " +
            "jugaba el juego de pelota ceremonial, representando la lucha entre las fuerzas " +
            "del bien y el mal."
        );
    }

    public static CulturalData getHistoricalContext() {
        return new CulturalData(
            "Contexto Histórico",
            "Durante el reinado de 18 Conejo (695-738 d.C.), Copán alcanzó su máximo " +
            "esplendor. El campo de pelota era usado para ceremonias religiosas y " +
            "rituales de sacrificio que conectaban con el inframundo maya."
        );
    }

    public static CulturalData getArchitecturalDetails() {
        return new CulturalData(
            "Detalles Arquitectónicos",
            "El campo mide aproximadamente 28 metros de largo. Los muros inclinados " +
            "están decorados con cabezas de guacamaya, símbolo del sol y la realeza. " +
            "Los marcadores centrales representan la entrada al inframundo."
        );
    }

    public static CulturalData getGameRules() {
        return new CulturalData(
            "El Juego Sagrado",
            "Los jugadores debían mantener una pelota de caucho en movimiento usando " +
            "solo caderas, codos y hombros. El juego tenía significado cosmológico: " +
            "representaba el movimiento del sol y los planetas."
        );
    }
}
